add_action( 'woocommerce_product_query', 'perfectpixel_hide_subcategory_products' );

function perfectpixel_hide_subcategory_products( $q ) {
	if ( ! is_product_category() ) {
		return;
	}
	$tax_query   = (array) $q->get( 'tax_query' );
	$tax_query[] = array(
		'taxonomy'         => 'product_cat',
		'field'            => 'term_id',
		'terms'            => array( get_queried_object_id() ),
		'include_children' => false,
	);
	$q->set( 'tax_query', $tax_query );
}
